def poly(z, k=2):
    import itertools as it
    return np.column_stack([np.ones(len(z))] + [np.prod(z[:, js], axis=1) for i in range(1, k + 1) for js in it.combinations_with_replacement(range(z.shape[1]), i)])

def report(A, Y, cv=False):
    if cv:
        splits = [(np.arange(52), np.arange(52, 72))] + [(p[:52], p[52:]) for p in [np.random.default_rng(i).permutation(72) for i in range(5)]]
        es = [np.abs(A[j] @ np.linalg.lstsq(A[i], Y[i], rcond=None)[0] - Y[j]).mean() for (i, j) in splits]
        return np.round([es[0], np.mean(es), max(es)], 5)
    Q = np.linalg.svd(A, full_matrices=False)[0][:, :np.linalg.matrix_rank(A)]
    r = Y - Q @ (Q.T @ Y)
    return np.round([np.abs(r).mean(), np.abs(r / (1 - (Q * Q).sum(1)[:, None])).mean(), *np.sqrt(np.mean(r * r, axis=0))], 6)

def basis(z, mode, w, linear):
    f = {'tanh': np.tanh, 'cos': np.cos, 'sin': np.sin}[mode]
    return np.c_[poly(z, 1) if linear else np.ones(len(z)), f(z * w)]

def calib(U, V, mode, linear):
    from scipy.optimize import minimize_scalar

    def obj(w):
        A = basis(U, mode, w, linear)
        R = A @ np.linalg.lstsq(A, V, rcond=None)[0] - V
        return np.mean(R ** 2)
    w = minimize_scalar(obj, bounds=(0.6, 3.3), method='bounded').x
    A = basis(U, mode, w, linear)
    c = np.linalg.lstsq(A, V, rcond=None)[0]
    return (w, lambda Z: basis(Z, mode, w, linear) @ c)
